include { HISAT2_ALIGN            } from 'nf-core/hisat2/align'
include { BAM_SORT_STATS_SAMTOOLS } from 'nf-core/bam_sort_stats_samtools'

workflow FASTQ_ALIGN_HISAT2 {
    take:
    reads // channel: [ val(meta), [ reads ] ]
    index // channel: /path/to/hisat2/index
    splicesites // channel: /path/to/genome.splicesites.txt
    ch_fasta_fai // channel: [meta, fasta, fai ]
    save_unaligned // val: boolean

    main:
    //
    // Map reads with HISAT2
    //
    HISAT2_ALIGN(reads, index, splicesites, save_unaligned)

    //
    // Sort, index BAM file and run samtools stats, flagstat and idxstats
    //
    BAM_SORT_STATS_SAMTOOLS(HISAT2_ALIGN.out.bam, ch_fasta_fai)

    emit:
    orig_bam = HISAT2_ALIGN.out.bam // channel: [ val(meta), bam   ]
    summary  = HISAT2_ALIGN.out.summary // channel: [ val(meta), log   ]
    fastq    = HISAT2_ALIGN.out.fastq // channel: [ val(meta), fastq ]
    bam      = BAM_SORT_STATS_SAMTOOLS.out.bam // channel: [ val(meta), [ bam ] ]
    index    = BAM_SORT_STATS_SAMTOOLS.out.index // channel: [ val(meta), [ index ] ]
    stats    = BAM_SORT_STATS_SAMTOOLS.out.stats // channel: [ val(meta), [ stats ] ]
    flagstat = BAM_SORT_STATS_SAMTOOLS.out.flagstat // channel: [ val(meta), [ flagstat ] ]
    idxstats = BAM_SORT_STATS_SAMTOOLS.out.idxstats // channel: [ val(meta), [ idxstats ] ]
}

nextflow_workflow {

    name "Test Subworkflow FASTQ_ALIGN_HISAT2"
    script "../main.nf"
    workflow "FASTQ_ALIGN_HISAT2"
    config "./nextflow.config"

    tag "hisat2"
    tag "hisat2/align"
    tag "hisat2/build"
    tag "hisat2/extractsplicesites"
    tag "samtools"
    tag "samtools/flagstat"
    tag "samtools/idxstats"
    tag "samtools/index"
    tag "samtools/sort"
    tag "samtools/stats"
    tag "subworkflows"
    tag "subworkflows/bam_sort_stats_samtools"
    tag "subworkflows/fastq_align_hisat2"
    tag "subworkflows_nfcore"

        setup {
            run("HISAT2_EXTRACTSPLICESITES") {
                script "../../../../modules/nf-core/hisat2/extractsplicesites/main.nf"
                process {
                    """
                    input[0] = channel.of([
                        [id: 'test'],
                        file(params.modules_testdata_base_path + "genomics/sarscov2/genome/genome.gtf", checkIfExists: true)
                    ])
                    """
                }
            }

            run("HISAT2_EXTRACTSPLICESITES", alias: "HISAT2_EXTRACTSPLICESITES_STUB") {
                script "../../../../modules/nf-core/hisat2/extractsplicesites/main.nf"
                process {
                    """
                    input[0] = channel.of([
                        [id: 'test'],
                        file(params.modules_testdata_base_path + "genomics/sarscov2/genome/genome.gtf", checkIfExists: true)
                    ])
                    """
                }
            }

            run("HISAT2_BUILD") {
                script "../../../../modules/nf-core/hisat2/build/main.nf"
                process {
                    """
                    input[0] = HISAT2_EXTRACTSPLICESITES.out.txt.map { meta, txt ->
                        [ meta,
                            file(params.modules_testdata_base_path + "genomics/sarscov2/genome/genome.fasta", checkIfExists: true),
                            file(params.modules_testdata_base_path + "genomics/sarscov2/genome/genome.gtf", checkIfExists: true),
                            txt
                        ]}
                    input[1] = false
                    """
                }
            }

            run("HISAT2_BUILD", alias: "HISAT2_BUILD_STUB") {
                script "../../../../modules/nf-core/hisat2/build/main.nf"
                process {
                    """
                    input[0] = HISAT2_EXTRACTSPLICESITES_STUB.out.txt.map { meta, txt ->
                        [ meta,
                            file(params.modules_testdata_base_path + "genomics/sarscov2/genome/genome.fasta", checkIfExists: true),
                            file(params.modules_testdata_base_path + "genomics/sarscov2/genome/genome.gtf", checkIfExists: true),
                            txt
                        ]}
                    input[1] = false
                    """
                }
            }
        }

    test("sarscov2 - bam - single_end") {

        when {
            workflow {
                """
                input[0] = channel.of([
                    [ id:'test', single_end:true ],
                    [
                        file(params.modules_testdata_base_path + "genomics/sarscov2/illumina/fastq/test_1.fastq.gz", checkIfExists: true)
                    ]
                ])
                input[1] = HISAT2_BUILD.out.index
                input[2] = HISAT2_EXTRACTSPLICESITES.out.txt
                input[3] = channel.of([
                    [ id:'test' ],
                    file(params.modules_testdata_base_path + "genomics/sarscov2/genome/genome.fasta", checkIfExists: true),
                    file(params.modules_testdata_base_path + "genomics/sarscov2/genome/genome.fasta.fai", checkIfExists: true)
                ])
                input[4] = false
                """
            }
        }

        then {
            assert workflow.success
            assertAll(
                { assert snapshot(sanitizeOutput(workflow.out, readsMD5Keys: ["bam"], unstableKeys: ["index", "orig_bam"])).match()}
            )
        }
    }
    test("sarscov2 - bam - paired_end") {

        when {
            workflow {
                """
                input[0] = channel.of([
                    [ id:'test', single_end:false ],
                    [
                        file(params.modules_testdata_base_path + "genomics/sarscov2/illumina/fastq/test_1.fastq.gz", checkIfExists: true),
                        file(params.modules_testdata_base_path + "genomics/sarscov2/illumina/fastq/test_2.fastq.gz", checkIfExists: true)
                    ]
                ])
                input[1] = HISAT2_BUILD.out.index
                input[2] = HISAT2_EXTRACTSPLICESITES.out.txt
                input[3] = channel.of([
                    [ id:'test' ],
                    file(params.modules_testdata_base_path + "genomics/sarscov2/genome/genome.fasta", checkIfExists: true),
                    file(params.modules_testdata_base_path + "genomics/sarscov2/genome/genome.fasta.fai", checkIfExists: true)
                ])
                input[4] = false
                """
            }
        }

        then {
            assert workflow.success
            assertAll(
                { assert snapshot(sanitizeOutput(workflow.out, readsMD5Keys: ["bam"], unstableKeys: ["index", "orig_bam"])).match()}
            )
        }
    }

    test("sarscov2 - bam - single_end - stub") {

        options "-stub"

        when {
            workflow {
                """
                input[0] = channel.of([
                    [ id:'test', single_end:true ],
                    [ file(params.modules_testdata_base_path + "genomics/sarscov2/illumina/fastq/test_1.fastq.gz", checkIfExists: true) ]
                ])
                input[1] = HISAT2_BUILD_STUB.out.index
                input[2] = HISAT2_EXTRACTSPLICESITES_STUB.out.txt
                input[3] = channel.of([
                    [ id:'test' ],
                    file(params.modules_testdata_base_path + "genomics/sarscov2/genome/genome.fasta", checkIfExists: true),
                    file(params.modules_testdata_base_path + "genomics/sarscov2/genome/genome.fasta.fai", checkIfExists: true)
                ])
                input[4] = false
                """
            }
        }

        then {
            assert workflow.success
            assertAll(
                { assert snapshot(sanitizeOutput(workflow.out)).match()}
            )
        }
    }
    test("sarscov2 - bam - paired_end - stub") {

        options "-stub"

        when {
            workflow {
                """
                input[0] = channel.of([
                    [ id:'test', single_end:false ],
                    [
                        file(params.modules_testdata_base_path + "genomics/sarscov2/illumina/fastq/test_1.fastq.gz", checkIfExists: true),
                        file(params.modules_testdata_base_path + "genomics/sarscov2/illumina/fastq/test_2.fastq.gz", checkIfExists: true)
                    ]
                ])
                input[1] = HISAT2_BUILD_STUB.out.index
                input[2] = HISAT2_EXTRACTSPLICESITES_STUB.out.txt
                input[3] = channel.of([
                    [ id:'test' ],
                    file(params.modules_testdata_base_path + "genomics/sarscov2/genome/genome.fasta", checkIfExists: true),
                    file(params.modules_testdata_base_path + "genomics/sarscov2/genome/genome.fasta.fai", checkIfExists: true)
                ])
                input[4] = false
                """
            }
        }

        then {
            assert workflow.success
            assertAll(
                { assert snapshot(sanitizeOutput(workflow.out)).match()}
            )
        }
    }
}

